  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Baricitinib, a high-transfer heteroaromatic kinase inhibitor analogue, has an absolute oral bioavailability of 80% in healthy volunteers, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Vilazodone, which shares indole and piperazine features with the query, has an absolute oral bioavailability of 72% in humans in the fed state, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "LSD, an indole-containing basic amine with high transferability, has an absolute oral bioavailability of 80% in healthy participants, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Belumosudil, a heteroaromatic kinase inhibitor analogue, has an absolute oral bioavailability of 64% after a 200 mg oral dose in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Abecarnil, despite first-pass variability, showed absolute oral bioavailability of 39 ± 17% (range 23-70%) in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bromerguride, the lowest-F analogue, still had 29% absolute oral bioavailability at 1 mg in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Brexpiprazole, a piperazine-containing oral drug, has 95% absolute oral bioavailability in healthy subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct human absolute bioavailability measurements (25-95%) exceed the 20% threshold; the query's heteroaromatic/piperazine drug-like structure is consistent with these analogues, so F is predicted high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule; prediction relies on high-transfer analogues.",
    "Some analogue F values are food/formulation dependent, but all remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

